#!/bin/bash
#
# Renovate post-upgrade task (postUpgradeTasks in .renovaterc.jsonc), run by the
# self-hosted Renovate of .github/workflows/chore-renovate.yml before it commits.
#
# Renovate's pip-compile manager recompiles each requirements/*.txt on its own and
# never moves a pin in a parent layer (_base -> _test -> _tools, see
# scripts/makefiles/requirements.mk), so an update can leave the lockfiles
# inconsistent or even unresolvable. This re-runs `make reqs upgrade="<pkg==ver ...>"`
# in every requirements directory the update touches or that pins one of the updated
# packages at another version. Renovate's versions are passed as exact pins on purpose:
# a bare `make reqs` upgrades everything and a bare package name lets uv pick the
# latest release. Only packages that block the update are passed by name (see
# resync_dir below).
#
# Usage: resync-lockfiles.bash [PINS_FILE]
#   PINS_FILE: one "<package>==<version>" per line, defaults to the data file
#   Renovate renders from postUpgradeTasks.dataFileTemplate
#
set -o errexit
set -o nounset
set -o pipefail

PINS_FILE="${1:-${RENOVATE_POST_UPGRADE_COMMAND_DATA_FILE:-}}"
if [[ -z "$PINS_FILE" || ! -f "$PINS_FILE" ]]; then
  echo "error: pins file not found: '${PINS_FILE}'" >&2
  exit 2
fi

cd "$(git rev-parse --show-toplevel)"

# Lines without a version (e.g. lock file maintenance) carry nothing to propagate.
# Renovate lists one upgrade per lockfile, so a branch can carry the same package at
# several versions (e.g. a security fix: the lowest fixed version for vulnerable
# lockfiles, a newer one for the others). uv cannot satisfy two exact pins of one
# package, so only the highest version of each (PEP 503-normalized) name is kept.
PINS=$(tr -d ' \r' <"$PINS_FILE" |
  { grep -E '^[A-Za-z0-9][A-Za-z0-9._-]*(\[[^]]+\])?==[A-Za-z0-9._+!-]+$' || true; } |
  awk -F'==' '{ name = tolower($1); sub(/\[[^]]*\]/, "", name); gsub(/[-_.]+/, "-", name); print name "\t" $2 "\t" $0 }' |
  sort -t "$(printf '\t')" -k1,1 -k2,2V |
  awk -F'\t' '{ highest[$1] = $3 } END { for (name in highest) print highest[name] }' |
  sort | tr '\n' ' ')
PINS="${PINS% }"
if [[ -z "$PINS" ]]; then
  echo "No version pins to propagate"
  exit 0
fi
echo "Propagating pins: $PINS"

# Lockfiles generated by pip-compile (same set as pip-compile.managerFilePatterns in .renovaterc.jsonc)
MANAGED='^(.*/)?requirements/_[^/]+\.txt$|^(api/tests|ci/helpers/requirements|tests/environment-setup/requirements)/requirements\.txt$'
LOCKS=$(git ls-files | grep -E "$MANAGED")

# Directories Renovate already modified (uncommitted at this point) ...
CHANGED=$(git diff --name-only HEAD | { grep -E "$MANAGED" || true; } | xargs -r -n1 dirname | sort -u)
# ... plus every directory pinning one of those packages at another version, so the
# version Renovate replaces cannot survive elsewhere in the monorepo. Names are
# compared PEP 503-normalized and without extras (`uvicorn[standard]==1.2` matches `uvicorn==1.2`)
# shellcheck disable=SC2016  # $0 and $i belong to the awk program
LAGGING=$(printf '%s\n' "$LOCKS" | xargs -r awk -v pins="$PINS" '
  function normalized(name) {
    sub(/\[[^]]*\]/, "", name)
    name = tolower(name)
    gsub(/[-_.]+/, "-", name)
    return name
  }
  BEGIN {
    npins = split(pins, pin, " ")
    for (i = 1; i <= npins; i++) {
      e = index(pin[i], "==")
      TARGET[normalized(substr(pin[i], 1, e - 1))] = substr(pin[i], e + 2)
    }
  }
  match($0, /^[A-Za-z0-9][A-Za-z0-9._-]*(\[[^]]+\])?==/) {
    name = normalized(substr($0, 1, RLENGTH - 2))
    if (name in TARGET && substr($0, RLENGTH + 1) != TARGET[name])
      print FILENAME
  }' | xargs -r -n1 dirname | sort -u)
DIRS=$(printf '%s\n%s\n' "$CHANGED" "$LAGGING" | { grep -v '^$' || true; } | sort -u)
if [[ -z "$DIRS" ]]; then
  echo "No lockfile needs regenerating"
  exit 0
fi
echo "Regenerating lockfiles in:"
while IFS= read -r dir; do echo "  - $dir"; done <<<"$DIRS"

BACKUP_DIR=$(mktemp -d)
trap 'rm -rf "$BACKUP_DIR"' EXIT

# Keeps the lockfiles as Renovate left them, to fall back to when a directory cannot
# be resolved (restoring from git would also drop Renovate's own changes)
snapshot() {
  mkdir -p "$BACKUP_DIR/$1"
  cp -p "$1"/*.txt "$BACKUP_DIR/$1/"
}
restore() {
  cp -p "$BACKUP_DIR/$1"/*.txt "$1/"
}

# Regenerates one directory with the given upgrade list. The inputs are touched first so
# the rules run even though the lockfiles may look newer than them (the Makefiles' own
# `touch` target is missing e.g. in api/tests).
regenerate() {
  local dir="$1"
  find "$dir" -maxdepth 1 -name '*.in' -exec touch {} +
  make -C "$dir" reqs upgrade="$2"
}

# Prints the (PEP 503-normalized) names of the packages uv's error message blames at
# exactly the version the directory's lockfiles pin, e.g. "packaging" for
# "virtualenv==21.14.10 depends on packaging>=26.3 and packaging==24.1", leaving out
# those the upgrade list already lets move. Only the error message counts: before it,
# the output holds the full lockfiles of the layers that did resolve, and every pin in
# there would otherwise look blamed.
blamed_pins() {
  local dir="$1" output="$2" upgrade="$3" blamed_file="$BACKUP_DIR/blamed"
  printf '%s\n' "$output" | awk '/^error:/ { in_error = 1 } /^make(\[[0-9]+\])?: / { in_error = 0 } in_error' |
    { grep -oE '[A-Za-z0-9][A-Za-z0-9._-]*==[A-Za-z0-9._+!-]*[A-Za-z0-9]' || true; } |
    sort -u >"$blamed_file"
  awk -v upgrade="$upgrade" '
    function normalized(name) {
      sub(/\[[^]]*\]/, "", name)
      name = tolower(name)
      gsub(/[-_.]+/, "-", name)
      return name
    }
    BEGIN {
      n = split(upgrade, entry, " ")
      for (i = 1; i <= n; i++) {
        split(entry[i], part, "==")
        FREE[normalized(part[1])] = 1
      }
    }
    FNR == NR {
      e = index($0, "==")
      BLAMED[normalized(substr($0, 1, e - 1)) "==" substr($0, e + 2)] = 1
      next
    }
    match($0, /^[A-Za-z0-9][A-Za-z0-9._-]*(\[[^]]+\])?==[^ ;]+/) {
      e = index($0, "==")
      name = normalized(substr($0, 1, e - 1))
      if ((name "==" substr($0, e + 2, RLENGTH - e - 1)) in BLAMED && !(name in FREE))
        print name
    }' "$blamed_file" "$dir"/*.txt | sort -u
}

# A lockfile is a hard constraint for uv, so a pin in another layer can leave Renovate's
# pins without solution (e.g. the new virtualenv in _tools.txt needs packaging>=26.3
# while _base.txt pins packaging==24.1). uv names such a pin in its error: that package
# is then allowed to move as well and the directory regenerated again, at most
# MAX_UNBLOCK_ROUNDS times. Only the packages that block the update move. A directory
# that still has no solution is left as Renovate produced it and reported.
MAX_UNBLOCK_ROUNDS=5
resync_dir() {
  local dir="$1" upgrade="$PINS" round output blamed
  for ((round = 0; round <= MAX_UNBLOCK_ROUNDS; round++)); do
    if output=$(regenerate "$dir" "$upgrade" 2>&1); then
      printf '%s\n' "$output"
      UNBLOCKED_BY="${upgrade#"$PINS"}"
      return 0
    fi
    printf '%s\n' "$output"
    restore "$dir"
    blamed=$(blamed_pins "$dir" "$output" "$upgrade" | tr '\n' ' ')
    blamed="${blamed% }"
    if [[ -z "$blamed" ]]; then
      return 1
    fi
    echo "warning: $dir: $blamed blocks \"$PINS\", letting it move too" >&2
    upgrade="$upgrade $blamed"
  done
  return 1
}

UNBLOCKED=""
FAILED=""
while IFS= read -r dir; do
  echo "--- $dir"
  snapshot "$dir"
  UNBLOCKED_BY=""
  if resync_dir "$dir"; then
    if [[ -n "$UNBLOCKED_BY" ]]; then
      UNBLOCKED="$UNBLOCKED $dir (${UNBLOCKED_BY# })"
    fi
  else
    FAILED="$FAILED $dir"
    restore "$dir"
  fi
done <<<"$DIRS"

if [[ -n "$UNBLOCKED" ]]; then
  echo "warning: these packages had to move too:$UNBLOCKED" >&2
fi
if [[ -n "$FAILED" ]]; then
  echo "error: could not regenerate the lockfiles in:$FAILED (left as Renovate produced them)" >&2
  exit 1
fi
